import React, { useState } from "react";
import { motion } from "framer-motion";
import { ShieldCheck, BookOpen, User, Users, UserCog } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

const roles = [
  {
    id: "student",
    title: "Student",
    description: "Create and manage your personal secure diary with advanced privacy features.",
    icon: <User className="w-10 h-10 text-blue-500" />,
    gradient: "from-blue-400 via-blue-500 to-blue-700"
  },
  {
    id: "teacher",
    title: "Teacher",
    description: "Guide students, monitor their progress, and ensure secure access to shared notes.",
    icon: <Users className="w-10 h-10 text-green-500" />,
    gradient: "from-green-400 via-green-500 to-green-700"
  },
  {
    id: "admin",
    title: "Admin",
    description: "Manage users, configure security policies, and oversee encrypted storage.",
    icon: <UserCog className="w-10 h-10 text-purple-500" />,
    gradient: "from-purple-400 via-purple-500 to-purple-700"
  }
];

export default function RoleSelection({ onRoleSelected }) {
  const [selectedRole, setSelectedRole] = useState(null);

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-black text-white flex flex-col">
      {/* Hero Section */}
      <header className="text-center py-12">
        <motion.h1
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-5xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 to-blue-600"
        >
          Secure E-Diary
        </motion.h1>
        <p className="mt-4 text-lg text-gray-300 max-w-2xl mx-auto">
          🛡️ Your private digital diary with <span className="text-cyan-400 font-semibold">biometric security</span>, 
          <span className="text-blue-400 font-semibold"> end-to-end encryption</span>, and 
          <span className="text-purple-400 font-semibold"> smart access control</span>. 
          Keep your thoughts safe, forever.
        </p>
      </header>

      {/* Role Selection */}
      <main className="flex-1 px-6 md:px-12 py-8">
        <h2 className="text-center text-2xl font-bold text-cyan-300 mb-8">
          Select Your Role
        </h2>
        <div className="grid md:grid-cols-3 gap-8 max-w-6xl mx-auto">
          {roles.map((role, index) => (
            <motion.div
              key={role.id}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.97 }}
              transition={{ type: "spring", stiffness: 200 }}
            >
              <Card
                className={`cursor-pointer rounded-2xl shadow-lg hover:shadow-2xl bg-gradient-to-br ${role.gradient} text-white`}
                onClick={() => {
                  setSelectedRole(role.id);
                  onRoleSelected?.(role.id);
                }}
              >
                <CardContent className="flex flex-col items-center p-6 space-y-4">
                  <div className="p-4 bg-white/20 rounded-full">{role.icon}</div>
                  <h3 className="text-xl font-bold">{role.title}</h3>
                  <p className="text-center text-sm">{role.description}</p>
                  <Button
                    variant="secondary"
                    className="mt-4 bg-white/20 hover:bg-white/30 text-white rounded-full"
                  >
                    Choose {role.title}
                  </Button>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      </main>

      {/* Footer */}
      <footer className="text-center py-6 text-gray-500 text-sm border-t border-gray-800">
        <div className="flex items-center justify-center space-x-2">
          <ShieldCheck className="w-5 h-5 text-cyan-400" />
          <span>Secure E-Diary © {new Date().getFullYear()}</span>
        </div>
      </footer>
    </div>
  );
}
